SELECT st.id,
'US_PROGRAM_MATH_OLYMPIAD_MATH_SPATIAL_0137',
'easy',
'You face north and turn right 2 times. Which direction do you face?',
'south',
'north',
'east',
'west',
'A',
'Each right turn is 90° clockwise.',
1,
'generated-original'
FROM education_subtopics st
JOIN education_topics t ON t.id=st.topic_id
JOIN education_subjects s ON s.id=t.subject_id
WHERE s.country_code='US'
  AND s.grade_code='PROGRAM_MATH_OLYMPIAD'
  AND s.subject_code='MATH'
  AND t.topic_code='GEOMETRY'
  AND st.subtopic_code='SPATIAL';

