SELECT st.id,
'IN_PROGRAM_MATH_OLYMPIAD_MATH_SPATIAL_0085',
'easy',
'You face north and turn right 1 time. Which direction do you face?',
'east',
'north',
'south',
'west',
'A',
'Each right turn is 90° clockwise.',
1,
'generated-original'
